import java.util.List;
import java.util.function.Function;
import java.util.function.IntSupplier;

record Payment(String id, long amountCents, String country) {}
record Rejection(String rule, String paymentId) {}

final class Rules {
    // a function value is an instance of a functional interface
    static Function<Payment, Rejection> amountAtMost(long limit) {
        return p -> p.amountCents() > limit ? new Rejection("amount-limit", p.id()) : null;   // captures limit
    }

    static Rejection firstRejection(Payment p, List<Function<Payment, Rejection>> rules) {
        return rules.stream()
                .map(rule -> rule.apply(p))          // called by its method name
                .filter(r -> r != null)
                .findFirst()
                .orElse(null);
    }

    // a captured local that changes is a compile error; the array is the box, built by hand
    static IntSupplier makeCounter() {
        int[] count = {0};
        return () -> ++count[0];
    }
}

kotlin.src:
data class Payment(val id: String, val amountCents: Long, val country: String)
data class Rejection(val rule: String, val paymentId: String)

typealias Rule = (Payment) -> Rejection?          // a real function type: Function1 on the JVM

fun amountAtMost(limit: Long): Rule = { p ->      // captures limit
    if (p.amountCents > limit) Rejection("amount-limit", p.id) else null
}

fun firstRejection(p: Payment, rules: List<Rule>): Rejection? =
    rules.firstNotNullOfOrNull { rule -> rule(p) }   // called like a function

// capturing a var is allowed; the compiler builds the Ref box for you
fun makeCounter(): () -> Int {
    var count = 0
    return { ++count }
}

