fun settle(batch: List<Payment>, pool: ExecutorService): Long {
    var settledCents = 0L
    val futures = batch.chunked(500).map { chunk ->
        pool.submit {
            chunk.forEach { p -> if (ledger.post(p)) settledCents += p.amountCents }
        }
    }
    futures.forEach { it.get() }
    return settledCents
}

