fun settle(batch: List<Payment>, pool: ExecutorService): Long {
    val futures = batch.chunked(500).map { chunk ->
        pool.submit(Callable {                                    // 1. each task returns a value
            chunk.sumOf { p -> if (ledger.post(p)) p.amountCents else 0L }
        })
    }
    return futures.sumOf { it.get() }                             // 2. combine on one thread
}

